"use strict";

async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const decoder = new TextDecoder("utf-8");

  let accepted = 0;
  let rejected = 0;
  let lineNumber = 1;
  let pending = "";
  let cancelled = false;

  async function cancelOnce() {
    if (!cancelled) {
      cancelled = true;
      await reader.cancel();
    }
  }

  async function visitLine(text, line) {
    if (text.endsWith("\r")) {
      text = text.slice(0, -1);
    }

    if (/^[ \t\r]*$/.test(text)) {
      return false;
    }

    let value;
    try {
      value = JSON.parse(text);
    } catch (_) {
      rejected++;
      return false;
    }

    const result = await visitor({ line, value });
    accepted++;
    return result === false;
  }

  async function consumeText(text) {
    let start = 0;

    while (true) {
      const end = text.indexOf("\n", start);
      if (end === -1) {
        pending += text.slice(start);
        return false;
      }

      const lineText = pending + text.slice(start, end);
      pending = "";

      if (await visitLine(lineText, lineNumber++)) {
        return true;
      }

      start = end + 1;
    }
  }

  try {
    while (true) {
      const result = await reader.read();

      if (result.done) {
        if (await consumeText(decoder.decode())) {
          await cancelOnce();
          return { accepted, rejected, stopped: true };
        }

        if (pending.length > 0) {
          if (await visitLine(pending, lineNumber++)) {
            await cancelOnce();
            return { accepted, rejected, stopped: true };
          }
        }

        return { accepted, rejected, stopped: false };
      }

      if (await consumeText(decoder.decode(result.value, { stream: true }))) {
        await cancelOnce();
        return { accepted, rejected, stopped: true };
      }
    }
  } catch (error) {
    await cancelOnce();
    throw error;
  } finally {
    reader.releaseLock();
  }
}
